css:
.log-body p { margin: 0 0 0.4em; }
.log-body p:last-child { margin-bottom: 0; }
.log-body ul, .log-body ol { margin: 0.3em 0; padding-left: 1.5em; }
.log-body pre { margin: 0.3em 0; white-space: pre-wrap; font-size: 0.9em; }
.log-mention { font-weight: 600; color: var(--log-accent); }
.log-audio { color: var(--log-muted); font-size: 0.9em; }
.pb { height: 0; }
.cu-text { margin: 0; white-space: pre-wrap; }
.log-node--message { margin: 0; padding: calc(var(--log-gap, 0.22) * 1em) 0; }
.log-node--message:not(.log-merged) { border-top: 0.5pt solid var(--log-rule); }
.log-node--message.log-merged { padding-top: 0; }
.log-node--element + .log-node--message { border-top-color: transparent; }
.log-node[data-log-type="dice"] { padding-left: 0.35em; padding-right: 0.35em; background: var(--log-tint); }
.cp { display: grid; grid-template-columns: calc(var(--log-avatarsize, 1.6) * 1em) 1fr; column-gap: 0.55em; align-items: start; line-height: var(--log-leading, 1.42); color: var(--log-ink); }
.cp-av { grid-column: 1; grid-row: 1; position: relative; width: calc(var(--log-avatarsize, 1.6) * 1em); height: calc(var(--log-avatarsize, 1.6) * 1em); margin: 0.08em 0 -0.2em; overflow: hidden; border-radius: 3px; background: var(--log-tint); box-shadow: inset 0 -2px 0 var(--log-speaker-color, var(--log-rule)); }
.cp-mono { display: block; height: 100%; overflow: hidden; word-break: break-all; text-align: center; font-size: calc(var(--log-avatarsize, 1.6) * 0.4em); line-height: 2.5; font-weight: 700; color: var(--log-speaker-color, var(--log-accent)); }
.cp-av .cp-img { position: absolute; top: 0; left: 0; width: 100%; height: 100%; max-width: none; max-height: none; object-fit: cover; }
.cp-main { grid-column: 2; grid-row: 1; min-width: 0; }
.log-merged .cp-av { visibility: hidden; height: 0; margin-top: 0; }
:root[data-log-showavatar="false"] .cp { grid-template-columns: 1fr; }
:root[data-log-showavatar="false"] .cp-av { display: none; }
:root[data-log-showavatar="false"] .cp-main { grid-column: 1; }
.cp-time { margin-right: 0.7em; font-size: 0.7em; color: var(--log-muted); font-variant-numeric: tabular-nums; }
:root[data-log-showtime="false"] .cp-time { display: none; }
.cp-name { margin-right: 0.6em; font-weight: 700; color: var(--log-speaker-color, var(--log-accent)); }
.cp-tag { display: inline-block; margin-right: 0.45em; padding: 0 0.3em; border: 0.5pt solid currentColor; border-radius: 2px; font-size: 0.68em; line-height: 1.5; letter-spacing: 0.04em; vertical-align: 0.12em; }
.log-merged .cp-name, .log-merged .cp-tag { display: none; }
.cp-text { display: inline; }
.cp-text p { margin: 0.12em 0 0; }
.cp-text p:first-child { display: inline; margin: 0; }
.cp-text img { display: inline-block; max-width: 48%; max-height: calc(var(--log-thumb, 8) * 1em); margin: 0.15em 0.35em 0.15em 0; vertical-align: top; border-radius: 2px; }
.cp-text blockquote { margin: 0.15em 0; padding-left: 0.6em; border-left: 2px solid var(--log-rule); color: var(--log-muted); }
.cp-ooc .cp-main { font-size: 0.9em; color: var(--log-muted); }
.cp-ooc .cp-av { opacity: 0.55; }
.cp-ooc .cp-name { font-weight: 600; color: var(--log-muted); }
.cp-dice .cp-text { font-family: "SFMono-Regular", Consolas, "Noto Sans Mono CJK SC", monospace; font-size: 0.92em; }
.cp-tag--dice { color: var(--log-accent); }
.cp-bot, .cp-bot .cp-name { color: var(--log-muted); }
.cp-bot .cp-main, .cp-narr .cp-main { grid-column: 2; }
:root[data-log-showavatar="false"] .cp-bot .cp-main, :root[data-log-showavatar="false"] .cp-narr .cp-main { grid-column: 1; }
.cp-narr .cp-main { padding-left: 0.7em; border-left: 2px solid var(--log-rule); }
.hd { margin: 1em 0 0.35em; padding: 0.22em 0.55em; background: var(--log-ink); font-size: 1em; font-weight: 800; line-height: 1.35; letter-spacing: 0.03em; color: var(--log-page-bg, #ffffff); break-after: avoid; }
[data-log-level="1"] .hd { padding: 0.35em 0.6em; font-size: 1.18em; }
[data-log-level="3"] .hd { padding: 0 0 0.1em; border-bottom: 1pt solid var(--log-ink); background: transparent; color: var(--log-ink); }
.tr { margin: 0.6em 0; text-align: var(--log-style-align, center); font-size: 0.78em; letter-spacing: 0.1em; color: var(--log-muted); background: linear-gradient(var(--log-rule), var(--log-rule)) center / 100% 1px no-repeat; }
.tr-label { padding: 0 0.7em; background: var(--log-page-bg, #ffffff); }
.qt { margin: 0.6em 0; padding: 0.1em 0 0.1em 0.8em; border-left: 2pt solid var(--log-ink); font-size: 0.92em; text-align: var(--log-style-align, left); color: var(--log-ink); }
.log-style-italic .qt { font-style: italic; }
.pro { margin: 0 0 0.9em; }
.pro-h { display: inline-block; margin: 0 0 0.35em; padding: 0 0.45em; background: var(--log-accent); font-size: 0.75em; font-weight: 800; letter-spacing: 0.12em; color: var(--log-page-bg, #ffffff); }
.pro-b { font-size: 0.95em; color: var(--log-ink); }
.cv { min-height: calc(var(--log-content-height, 180mm) * 0.9); display: flex; flex-direction: column; justify-content: flex-end; padding-bottom: 12%; break-after: page; }
.cv-fig { margin: 0 0 1.4em; }
.cv-fig img { max-height: calc(var(--log-content-height, 180mm) * 0.5); }
.cv-bar { width: 3em; height: 0.35em; margin-bottom: 1em; background: var(--log-accent); }
.cv-title { margin: 0 0 0.3em; font-size: 2em; font-weight: 800; line-height: 1.2; color: var(--log-ink); }
.cv-sub { margin: 0; color: var(--log-muted); }
.ip { margin: 0.6em 0; break-inside: avoid; }
.ip img { display: block; }
.ip figcaption { margin-top: 0.25em; font-size: 0.78em; color: var(--log-muted); }
.ip figcaption::before { content: "图　"; font-weight: 700; color: var(--log-ink); }
.toc { break-after: page; }
.toc-h { margin: 0 0 0.4em; padding-bottom: 0.15em; border-bottom: 1.5pt solid var(--log-ink); font-size: 1.1em; font-weight: 800; }
.toc .log-toc-item { padding: 0.12em 0; border-bottom: 0.5pt solid var(--log-rule); font-size: 0.92em; }
.cu { margin: 0.8em 0; border: 1pt solid var(--log-ink); break-inside: avoid; }
.log-style-accent .cu { border-color: var(--log-accent); border-width: 2pt; }
.cu-title { padding: 0.1em 0.5em; background: var(--log-ink); font-size: 0.85em; font-weight: 800; color: var(--log-page-bg, #ffffff); }
.cu-text { padding: 0.4em 0.6em; }
.cu-note { margin: 0; padding: 0 0.6em 0.4em; font-size: 0.82em; color: var(--log-muted); }
.ph, .pf { width: 100%; display: flex; justify-content: space-between; gap: 1em; }
.ph-title { font-weight: 700; }
.pf-num::before { content: "p. "; }
.cp-whisper { display: inline-block; max-width: 100%; margin-right: 0.45em; padding: 0 0.3em; border: 0.5pt dashed var(--log-accent); border-radius: 2px; font-size: 0.68em; line-height: 1.5; letter-spacing: 0.02em; color: var(--log-accent); vertical-align: 0.12em; overflow-wrap: anywhere; }
.log-merged .cp-whisper { display: none; }
.log-node--message[data-log-whisper] { padding-left: 0.35em; background-image: linear-gradient(var(--log-accent), var(--log-accent)); background-size: 2px 100%; background-repeat: no-repeat; }
.cp-quote { display: flex; gap: 0.4em; margin: 0 0 0.05em; font-size: 0.75em; line-height: 1.4; color: var(--log-muted); }
.cp-quote::before { content: "↳"; flex: none; }
.cp-quote-who { flex: none; max-width: 40%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-weight: 700; }
.cp-quote-text { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cp-text .log-embed { display: block; margin: 0.15em 0; padding: 0.2em 0.5em; border: 0.5pt solid var(--log-rule); border-left: 2pt solid var(--log-accent); background: var(--log-tint); }
.cp-text .log-embed p:first-child { display: block; }
@media print {
  .log-node--message[data-log-whisper] { padding-left: 0; background-image: none; }
}
.cp-act { margin-right: 0.45em; font-size: 0.72em; color: var(--log-muted); }
.log-merged .cp-act { display: none; }
.cp-text .log-embed--world-clue { padding: 0; border: 0; background: none; }
.log-clue { display: grid; grid-template-columns: 1fr; margin: 0.15em 0; padding: 0.2em 0.5em 0.3em; border: 0.5pt solid var(--log-rule); border-left: 2pt solid var(--log-accent); background: var(--log-tint); }
.log-clue + .log-clue { margin-top: 0.3em; }
.log-clue--iframe { border-left-style: dashed; }
.log-clue__head { display: flex; flex-wrap: wrap; align-items: baseline; gap: 0 0.45em; margin-bottom: 0.1em; line-height: 1.45; break-inside: avoid; break-after: avoid; }
.log-clue__label { padding: 0 0.3em; border: 0; border-radius: 0; background: var(--log-accent); font-size: 0.66em; font-weight: 800; letter-spacing: 0.1em; color: var(--log-page-bg, #ffffff); }
.log-clue__title { min-width: 0; font-weight: 800; color: var(--log-ink); overflow-wrap: anywhere; }
.log-clue__kind { padding: 0 0.3em; border: 0.5pt solid currentColor; border-radius: 2px; font-size: 0.66em; color: var(--log-muted); }
.log-clue__body { min-width: 0; font-size: 0.95em; }
.log-clue__body--empty { font-size: 0.85em; color: var(--log-muted); }
.log-clue__media { break-inside: avoid; }
.cp-text .log-clue__media img { display: block; max-width: 100%; max-height: calc(var(--log-thumb, 8) * 1.5em); margin: 0.15em 0; }
.log-clue__media--missing { font-size: 0.8em; color: var(--log-muted); }
.log-clue--image { grid-template-columns: auto 1fr; column-gap: 0.6em; }
.log-clue--image .log-clue__media { grid-column: 1; grid-row: 1 / span 4; }
.cp-text .log-clue--image .log-clue__media img { max-width: 9em; margin: 0.1em 0; }
.log-clue--image .log-clue__head, .log-clue--image .log-clue__body, .log-clue--image .log-clue__source { grid-column: 2; min-width: 0; }
.log-clue--image .log-clue__media--missing { grid-column: 1 / span 2; grid-row: auto; }
.log-clue__source { font-size: 0.72em; color: var(--log-muted); overflow-wrap: anywhere; }
.log-clue__source-label { margin-right: 0.35em; font-weight: 700; color: var(--log-ink); }
.log-clue__source-label::after { content: none; }
@media print {
  .log-clue { background: none; }
}
@media (max-width: 480px) {
  .log-clue--image { grid-template-columns: 1fr; }
  .log-clue--image .log-clue__head, .log-clue--image .log-clue__media, .log-clue--image .log-clue__body, .log-clue--image .log-clue__source { grid-column: 1; grid-row: auto; }
}
